"""Render the exact, readable Stage-D owner approval record."""
import json
from pathlib import Path
P=Path(__file__).resolve().parents[1];W=P.parent
read=lambda p:json.loads(p.read_text());rows=[]
for x in read(P/'d3/calculus-deviations.json'):
 if x['deviation_id']=='CALC-D3-DEV11':continue
