rows += [
 dict(id='D2-MOTION-LIVE-CHECK',recipe='WB8227-motion-integration',part='interior-reversal:distance R1–R4 / displacement R5–R6',official_row='Textbook-derived branch; calculus anchors: 2021 P1 Q4, report PDF232, and 2023 P2 Q9, report PDF339. OD-4 requires the live decision.',departure='Proposed fixed 4+2 rubric over 144 sign-change and 24 no-change cases. R1 admits a complete constant-sign proof or a coherent root/interval check; R3 needs primitive and bounds, with own-root F.T.; R4 requires www. R5 signed legs must be primitive-based.',rationale='The owner accepted the design direction, not this exact tariff. Mark the actual decomposition decision; a false interior root with a coincident no-change total gets 3/4.',status_class='active proposed marking adaptation',status='OD-4 direction accepted; exact tariff, domain and rubric pending final manifest approval.'),
 dict(id='D1-MOTION-QUADRATIC',recipe='WB8227-motion-integration',part='historical version 0.1.1 reversal',official_row='D1 proposed 4+2 rubric.',departure='Superseded by D2-MOTION-LIVE-CHECK and its version 0.1.3 domain/rubric. Saved historical versions retain their original bytes.',rationale='Keep the history traceable without using a fixed-outcome design as evidence of the current Analyse demand.',status_class='historical/superseded',status='Not separately requested for approval.'),
 dict(id='OD-6',recipe='all nine recipes',part='all 27 parts; genuinely misread question datum',official_row='NSSCAS 2025 report PDF345 item4 / CONVENTION108: no maximum after misread. Comparable Cambridge 9709_m16_ms_12.pdf PDF3 Penalties supplies the owner-adopted allocation.',departure='Owner chose one earned A/B deduction per eligible datum in its first-use part; all A/B F.T., M/DM usual. Earliest eligible earned A/B in declared order; none earned means no deduction or borrowing. No later-part second deduction.',rationale='Replace the withdrawn D2 allocation. Exponential V=12→21 becomes 4/5; vector OB sign misread becomes 6/7. Own figures or changed object/difficulty receive ordinary canonical treatment. Correct working, named errors, supplied-target proof restrictions and OD-1 remain.',status_class='binding owner decision',status='OD-6 settled; application of the rule is part of the pending exact candidate confirmation.'),
 dict(id='D1-MOD-OD1-LIST',recipe='WB8227-modulus-graph-recovery',part='a:B1–B3',official_row='2023 P2 Q2, report PDF331: correct values www, including a formula.',departure='Withdrawn list-zero/formula-three distinction. Correct named values and correct formula entries each earn the same B1 www awards.',rationale='Apply the official exception consistently to the evidence, regardless of input form.',status_class='withdrawn erroneous interpretation',status='No approval requested for the withdrawn rule.')]
assert len(rows)==len({x['id']for x in rows})==20
for row in rows:
 for k,v in row.items():
  if isinstance(v,str):row[k]=v.replace('Apply3','Apply 3').replace('all27','all 27')
 assert row['status_class']and all(row.get(k)for k in ['departure','rationale','official_row'])
